Lemma hm_mid : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' xs5 : word)
    (P verb spa lo shi ff fp : Z) (h : hdrv) (LF : list fframe) (m m2 : mem) (j48 v16 junk1 junk2 : list byte),
  rw_cells bsegs m2 (bv_unsigned sp + -128) [C8 (Z_to_bv 64 0); CB 48 j48; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells bsegs m2 (bv_unsigned sp + -144) [CB 16 v16] ->
  rw_cells bsegs m2 ff [CB 24 junk1; C8 (Z_to_bv 64 spa); CB 24 junk2; C8 (Z_to_bv 64 fp)] ->
  SHAD m2 ff (poison_bytes 8 0) ->
  rw_cells bsegs m2 fp [C1 (b8 1)] ->
  stk bsegs m2 lo (bv_unsigned sp + -144) -> mem_inv bsegs m2 ->
  as_RFS H ((0, ff, fp) :: LF) m2 -> ACONST m2 -> stack0 m2 lo shi ->
  munch (hm_W lo sp P ff fp) m m2 -> wmono bsegs m m2 ->
  (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144) ->
  lo + HM_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *)
  rw_cells bsegs m2 (P + O_PR_HDR) [C8 (wz (hv_mp h)); C8 (wz 0); C8 (wz (hv_tp h)); C8 (wz (hv_tl h)); C4 (wz (hv_ver h)); C4 (wz (hv_vb h))] ->
  hv_ml h = 0 -> 1 <= verb < 2^32 ->
  as_RFS H LF m -> 0 <= P -> aapp P 256 -> P mod 8 = 0 -> accessible m2 P 256 -> fsobj H LF P 256 ->
